CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, actor TEXT NOT NULL, role TEXT NOT NULL, region TEXT, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fields (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, season INTEGER NOT NULL, region_id TEXT NOT NULL, geometry TEXT NOT NULL, crop TEXT NOT NULL, area_ha REAL NOT NULL, declared_ha REAL, start TEXT NOT NULL, end TEXT NOT NULL, families INTEGER NOT NULL, price INTEGER, status TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'private', version INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS fields_visible ON fields(status,season,region_id);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, role TEXT NOT NULL, region_id TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS regions (id TEXT PRIMARY KEY, status TEXT NOT NULL, external TEXT);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deletions (id TEXT PRIMARY KEY, kind TEXT NOT NULL, created TEXT NOT NULL);
